const nn = (...xs) => xs.every((x) => x !== null && x !== undefined);
function snapAt(rows, day) { // latest snapshot with filed < day
  let best = null;
  for (let i = 0; i < rows.length; i++) { if (rows[i][0] < day) best = rows[i]; else break; }
  return best;
}
const obj = (row) => { if (!row) return null; const o = {}; for (const k in COL) o[k] = row[COL[k]]; return o; };

export function rank(universe, t, ctx) {
  const day = t / 86400;
  const out = [];
  for (const sym of Object.keys(universe)) {
    const rows = D[sym];
    if (!rows) continue;
    const bars = universe[sym];
    const px = bars[bars.length - 1].close;
    const cur = snapAt(rows, day);
    if (!cur || day - cur[0] > ctx.params.stale) continue;
    const prv = snapAt(rows, day - 365);
    const r = obj(cur), p = obj(prv);
    if (!nn(r.sh) || !(r.sh > 0) || !(px > 0)) continue;
    const mc = px * r.sh;
    const s = (() => { if (!p || !nn(r.ni, r.assets) || !(r.assets > 0) || !nn(p.ni, p.assets) || !(p.assets > 0)) return null;
    const roa = r.ni / r.assets, roaP = p.ni / p.assets;
    let f = 0;
    if (roa > 0) f++;
    if (nn(r.cfo) && r.cfo > 0) f++;
    if (roa > roaP) f++;
    if (nn(r.cfo) && r.cfo > r.ni) f++;
    if (nn(r.liab, p.liab) && r.liab / r.assets < p.liab / p.assets) f++;
    if (nn(r.ca, r.cl, p.ca, p.cl) && r.cl > 0 && p.cl > 0 && r.ca / r.cl > p.ca / p.cl) f++;
    if (nn(r.sh, p.sh) && r.sh <= p.sh * 1.02) f++;
    if (nn(r.gp, r.rev, p.gp, p.rev) && r.rev > 0 && p.rev > 0 && r.gp / r.rev > p.gp / p.rev) f++;
    if (nn(r.rev, p.rev) && r.rev / r.assets > p.rev / p.assets) f++;
    return f; })();
    if (s !== null && s !== undefined) out.push([sym, s]);
  }
  const n = out.length;
  const w = {};
  if (n < ctx.params.minEligible) return w;
  const pick = out.filter((x) => x[1] >= ctx.params.fscoreMin);
  if (pick.length < ctx.params.minHold) return w;
  for (const [sym] of pick) w[sym] = 1 / pick.length;
  return w;
}
